const REQUEST_META_LABEL = "beleidskompas-request";
const TITLE_REQUEST_MARKER = "__BELEIDSKOMPAS_TITLE_REQUEST__";
const MESSAGES = {"unknown_step":"Beleidskompas kon niet bepalen voor welke stap dit bericht is en heeft het daarom niet beantwoord. Stel je vraag opnieuw vanaf de Beleidskompas-pagina, met een stap gekozen.","store_missing":"Beleidskompas kan zijn opslag niet gebruiken en heeft dit bericht daarom niet beantwoord. Meld dit bij de beheerder.","store_failed":"De opslag van Beleidskompas gaf een fout. Dit bericht is daarom niet beantwoord; probeer het later opnieuw.","store_warning":"Let op: de opslag van Beleidskompas gaf een fout. Dit antwoord is mogelijk niet bewaard.","no_answer":"Beleidskompas kon dit bericht niet beantwoorden. Probeer het later opnieuw."};

function extractSuppliedToken(headers) {
  const h = headers && typeof headers === 'object' ? headers : {};
  const direct = String(h['x-govchat-token'] || h['X-Govchat-Token'] || '').trim();
  if (direct) return direct;
  // The n8n-openai-bridge (LibreChat's real custom-endpoint pipeline) sends the
  // shared webhook secret as a standard Authorization bearer token instead of
  // the x-govchat-token header used by direct/manual webhook calls.
  const authHeader = String(h['authorization'] || h['Authorization'] || '').trim();
  if (/^Bearer\s/i.test(authHeader)) {
    return authHeader.slice(authHeader.indexOf(' ') + 1).trim();
  }
  return '';
}

function parsePageMessage(text) {
  const raw = String(text || '');
  const parts = { fromPage: false, substepId: '', message: raw.trim(), shown: raw.trim() };
  const marker = `[${REQUEST_META_LABEL}]: data:application/json;base64,`;
  const idx = raw.lastIndexOf(marker);
  if (idx === -1) return parts;

  let request;
  try {
    const encoded = raw.slice(idx + marker.length).split('\n')[0].trim();
    request = JSON.parse(Buffer.from(encoded, 'base64').toString('utf8'));
  } catch (_) {
    return parts;
  }
  parts.fromPage = true;
  parts.shown = raw.slice(0, idx).trim();
  parts.substepId = String(request.substep_id || '').trim();
  parts.message = String(request.message || '').trim();
  return parts;
}

function isTitleRequest(text) {
  return String(text || '').includes(TITLE_REQUEST_MARKER);
}

function extractConvoUserText(text) {
  const s = String(text || '');
  const userIdx = s.indexOf('User:');
  if (userIdx === -1) return s.trim();
  const afterUser = s.slice(userIdx + 'User:'.length);
  const aiIdx = afterUser.indexOf('\nAI:');
  return (aiIdx === -1 ? afterUser : afterUser.slice(0, aiIdx)).trim();
}

function incomingMessage(body) {
  const b = body && typeof body === 'object' ? body : {};
  return String(b.currentMessage || b.chatInput || b.question || '');
}

function failure(base, error, text) {
  return { step_id: null, ...base, ok: false, error, text, answer: text };
}

function prepareRequest({ body, headers, env, now }) {
  const b = body && typeof body === 'object' ? body : {};
  const started_at = now;
  const refuse = (error, text) => failure({ kind: 'refused', started_at }, error, text);

  // A wrong token gives a normal answer with ok: false, not a thrown error:
  // n8n can turn a thrown error into an empty response, and then the caller
  // sees nothing at all.
  const expectedToken = String((env && env.N8N_WEBHOOK_TOKEN) || '').trim();
  if (expectedToken && extractSuppliedToken(headers) !== expectedToken) return refuse('Unauthorized webhook token', '');

  const case_id = String(b.sessionId || '').trim();
  const user_id = String(b.userId || '').trim();

  // LibreChat asks for a conversation title through this same endpoint. That
  // request carries TITLE_REQUEST_MARKER (set in librechat.yaml), sometimes
  // in systemPrompt and sometimes in the message itself.
  const text = incomingMessage(b);
  if (isTitleRequest(text) || isTitleRequest(String(b.systemPrompt || ''))) {
    // The title is made from what the user wrote, not from the block the
    // page put behind it.
    const conversation = parsePageMessage(extractConvoUserText(text.replaceAll(TITLE_REQUEST_MARKER, '')));
    const title_source = conversation.message || conversation.shown;
    return { kind: 'title', ok: true, case_id, user_id, title_source: title_source.slice(0, 2000), started_at };
  }

  const storeConfigured = Boolean(String((env && env.BELEIDSKOMPAS_STORE_URL) || '').trim() && String((env && env.BELEIDSKOMPAS_STORE_TOKEN) || '').trim());
  if (!storeConfigured) return refuse('Store not configured', MESSAGES.store_missing);
  if (!case_id || !user_id) return refuse('No conversation or user from the bridge', MESSAGES.store_missing);

  const parts = parsePageMessage(text);
  return {
    kind: parts.message ? 'message' : 'report',
    ok: true,
    case_id,
    user_id,
    substep_id: parts.substepId,
    message: parts.message,
    started_at,
  };
}

return [{ json: prepareRequest({
  body: $json.body,
  headers: $json.headers,
  env: {
    N8N_WEBHOOK_TOKEN: $env.N8N_WEBHOOK_TOKEN,
    BELEIDSKOMPAS_STORE_URL: $env.BELEIDSKOMPAS_STORE_URL,
    BELEIDSKOMPAS_STORE_TOKEN: $env.BELEIDSKOMPAS_STORE_TOKEN,
  },
  now: Date.now(),
}) }];

const TITLE_REQUEST_MARKER = "__BELEIDSKOMPAS_TITLE_REQUEST__";
const TITLE_PREFIX = "Beleidskompas - ";

function nodeError(output) {
  const error = output && output.error;
  if (!error) return null;
  return String((typeof error === 'object' && error.message) || error);
}

function buildFallbackTitle(text) {
  const cleaned = String(text || '')
    .replaceAll(TITLE_REQUEST_MARKER, '')
    .replace(/[#*_`]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
  if (!cleaned) return 'Beleidskompas casus';
  const words = cleaned.split(' ').slice(0, 8);
  const joined = words.join(' ');
  return joined.length < cleaned.length ? joined + '…' : joined;
}

function buildTitle({ request, reply }) {
  const raw = nodeError(reply) ? '' : String((reply && reply.text) || '');
  const wrapperChars = new Set(['"', "'", '#', '*', '_']);
  let start = 0;
  let end = raw.length;
  while (start < end && (wrapperChars.has(raw[start]) || /\s/.test(raw[start]))) start += 1;
  while (end > start && (wrapperChars.has(raw[end - 1]) || /\s/.test(raw[end - 1]))) end -= 1;
  // Prefixed so Beleidskompas conversations are visually grouped in
  // LibreChat's conversation-list sidebar, alongside other endpoints/agents.
  const title = TITLE_PREFIX + (raw.slice(start, end) || buildFallbackTitle(request.title_source));
  return { ok: true, step_id: null, mode: 'title', case_id: request.case_id, user_id: request.user_id, answer: title, text: title };
}

return [{ json: buildTitle({ request: $('Verzoek voorbereiden').first().json, reply: $json }) }];

const MESSAGES = {"unknown_step":"Beleidskompas kon niet bepalen voor welke stap dit bericht is en heeft het daarom niet beantwoord. Stel je vraag opnieuw vanaf de Beleidskompas-pagina, met een stap gekozen.","store_missing":"Beleidskompas kan zijn opslag niet gebruiken en heeft dit bericht daarom niet beantwoord. Meld dit bij de beheerder.","store_failed":"De opslag van Beleidskompas gaf een fout. Dit bericht is daarom niet beantwoord; probeer het later opnieuw.","store_warning":"Let op: de opslag van Beleidskompas gaf een fout. Dit antwoord is mogelijk niet bewaard.","no_answer":"Beleidskompas kon dit bericht niet beantwoorden. Probeer het later opnieuw."};
const STEP_IDS = ["stap1","stap2","stap3","stap4"];

function nodeError(output) {
  const error = output && output.error;
  if (!error) return null;
  return String((typeof error === 'object' && error.message) || error);
}

function failure(base, error, text) {
  return { step_id: null, ...base, ok: false, error, text, answer: text };
}

function stepFromTemplate(template, stepId) {
  const steps = template && Array.isArray(template.steps) ? template.steps : [];
  const index = steps.findIndex((step) => step && step.id === stepId);
  if (index === -1) return null;
  const step = steps[index];
  const nr = Number(step.nr) || index + 1;
  return {
    id: step.id,
    nr,
    title: String(step.title || ''),
    role: String(step.prompt || ''),
    // The label is the number a person sees: the step number and the place in the step.
    // The id stays the same when a substep moves, so the stored reports keep their substep.
    // Same rule in overlay/src/apps/beleidskompas/config.js and the admin Flow builder
    // (services/admin-overlay/admin/views/beleidskompas-admin/pages/flow.js): change all three.
    substeps: (Array.isArray(step.substeps) ? step.substeps : []).map((substep, position) => ({
      id: substep.id,
      label: `${nr}.${position + 1}`,
      title: String(substep.title || ''),
      instruction: String(substep.prompt || ''),
      format: String(substep.answer_format || ''),
    })),
  };
}

function stepToolName(step) {
  return `${step.id}_agent`;
}

function buildOrchestratorPrompt(steps, promptText) {
  const list = steps
    .map((step, index) => {
      const substeps = step.substeps.map((substep) => `${substep.label} ${substep.title}`).join(', ');
      return `- ${stepToolName(step)}: stap ${step.nr || index + 1}, ${step.title} (${substeps})`;
    })
    .join('\n');
  return String(promptText || '').replaceAll('{{steps}}', list);
}

function buildContext({ request, state, live, stepIds }) {
  const flow = live && live.flow;
  const templateError = nodeError(live) || (flow && Array.isArray(flow.steps) ? null : 'No template in the answer of the admin');
  if (templateError) return failure(request, `template: ${templateError}`, MESSAGES.store_failed);

  const stateError = nodeError(state) || (state && state.reports !== null && typeof state.reports === 'object' ? null : 'No state in the answer of the store');
  if (stateError) return failure(request, `state: ${stateError}`, MESSAGES.store_failed);

  const steps = flow.steps
    .filter((step) => step && Array.isArray(step.substeps) && stepIds.includes(step.id))
    .map((step) => stepFromTemplate(flow, step.id));
  const substeps = steps.flatMap((step) => step.substeps);
  const order = substeps.map((substep) => substep.id);
  const substep_id = order.includes(request.substep_id) ? request.substep_id : '';
  // The models read the number a person sees, not the id.
  const label = substep_id ? substeps.find((substep) => substep.id === substep_id).label : '';
  if (request.kind === 'report' && !substep_id) return failure(request, 'No substep recognised in the request', MESSAGES.unknown_step);

  const model = String((live.settings && live.settings.default_model) || '').trim() || 'govchat-default';
  const step_templates = {};
  for (const step of steps) {
    step_templates[step.id] = JSON.stringify({
      model,
      rules: String(flow.rules || ''),
      report_prompt: String(flow.report_prompt || ''),
      conversation_prompt: String(flow.conversation_prompt || ''),
      report_disclaimer: String(flow.report_disclaimer || ''),
      step,
    });
  }

  const reports = state.reports;
  // Only reports of substeps in the template: the page hides the others too.
  const ids = Object.keys(reports)
    .filter((id) => order.includes(id))
    .sort((a, b) => order.indexOf(a) - order.indexOf(b));
  const reportTexts = (reportIds) =>
    reportIds
      .map((id) => String(reports[id].text || '').trim())
      .filter(Boolean)
      .join('\n\n');

  const upTo = request.kind === 'report' ? order.indexOf(substep_id) : -1;
  const findings = reportTexts(ids.filter((id) => upTo === -1 || order.indexOf(id) <= upTo));
  const allReports = reportTexts(ids);
  const turns = Array.isArray(state.turns) ? state.turns : [];
  const conversation = turns.map((t) => `${t.role === 'user' ? 'Gebruiker' : 'Beleidskompas'}: ${String(t.text || '').trim()}`).join('\n');
  // The documents the user uploaded in this chat, in full, for every step.
  const uploaded = Array.isArray(state.documents) ? state.documents : [];
  const documents = uploaded.length ? `Documenten van de gebruiker:\n\n${uploaded.map((d) => `### ${d.filename}\n${String(d.text || '').trim()}`).join('\n\n')}` : '';
  const asked =
    request.kind === 'message'
      ? `Bericht van de gebruiker (de gebruiker zit in deelstap ${label || 'onbekend'}):\n${request.message}`
      : `Verzoek: werk deelstap ${label} uit.`;

  const prompt = [
    documents,
    allReports ? `Bevindingen tot nu toe:\n${allReports}` : 'Bevindingen tot nu toe: (nog geen deelstap uitgewerkt)',
    conversation && `Laatste beurten van het gesprek:\n${conversation}`,
    asked,
  ]
    .filter(Boolean)
    .join('\n\n');

  return {
    ...request,
    substep_id,
    findings,
    conversation,
    documents,
    prompt,
    system_prompt: buildOrchestratorPrompt(steps, flow.orchestrator_prompt),
    model,
    step_templates,
  };
}

return [{ json: buildContext({ request: $('Verzoek voorbereiden').first().json, state: $json, live: $('Template ophalen').first().json, stepIds: STEP_IDS }) }];

