function userTurnFailure({ saved }) {
  return failure({}, `user_turn: ${nodeError(saved)}`, MESSAGES.store_failed);
}

return [{ json: userTurnFailure({ saved: $json }) }];

const MESSAGES = {"unknown_step":"Beleidskompas kon niet bepalen voor welke stap dit bericht is en heeft het daarom niet beantwoord. Stel je vraag opnieuw vanaf de Beleidskompas-pagina, met een stap gekozen.","store_missing":"Beleidskompas kan zijn opslag niet gebruiken en heeft dit bericht daarom niet beantwoord. Meld dit bij de beheerder.","store_failed":"De opslag van Beleidskompas gaf een fout. Dit bericht is daarom niet beantwoord; probeer het later opnieuw.","store_warning":"Let op: de opslag van Beleidskompas gaf een fout. Dit antwoord is mogelijk niet bewaard.","no_answer":"Beleidskompas kon dit bericht niet beantwoorden. Probeer het later opnieuw."};

function toolCalls(agentOutput) {
  const steps = agentOutput && Array.isArray(agentOutput.intermediateSteps) ? agentOutput.intermediateSteps : [];
  return steps.map((step) => ({
    tool: (step && step.action && step.action.tool) || null,
    input: step && step.action ? step.action.toolInput : null,
  }));
}

function nodeError(output) {
  const error = output && output.error;
  if (!error) return null;
  return String((typeof error === 'object' && error.message) || error);
}

function failure(base, error, text) {
  return { step_id: null, ...base, ok: false, error, text, answer: text };
}

function buildAnswer({ context, agent, now }) {
  const tools = toolCalls(agent);
  const error = nodeError(agent);
  const text = error ? '' : String((agent && agent.output) || '').trim();
  const called = tools.map((t) => /^(.+)_agent$/.exec(String(t.tool || ''))).find(Boolean);

  const base = {
    case_id: context.case_id,
    user_id: context.user_id,
    mode: context.kind === 'report' ? 'report' : 'conversation',
    step_id: called ? called[1] : null,
    asked_from: context.substep_id || null,
    tools,
    duration_ms: now - context.started_at,
  };
  if (!text) return failure(base, error || 'The orchestrator returned no text', MESSAGES.no_answer);
  return { ...base, ok: true, text, answer: text };
}

return [{ json: buildAnswer({ context: $('Gegevens voor de agents klaarzetten').first().json, agent: $json, now: Date.now() }) }];

