const MESSAGES = {"unknown_step":"Beleidskompas kon niet bepalen voor welke stap dit bericht is en heeft het daarom niet beantwoord. Stel je vraag opnieuw vanaf de Beleidskompas-pagina, met een stap gekozen.","store_missing":"Beleidskompas kan zijn opslag niet gebruiken en heeft dit bericht daarom niet beantwoord. Meld dit bij de beheerder.","store_failed":"De opslag van Beleidskompas gaf een fout. Dit bericht is daarom niet beantwoord; probeer het later opnieuw.","store_warning":"Let op: de opslag van Beleidskompas gaf een fout. Dit antwoord is mogelijk niet bewaard.","no_answer":"Beleidskompas kon dit bericht niet beantwoorden. Probeer het later opnieuw."};

function nodeError(output) {
  const error = output && output.error;
  if (!error) return null;
  return String((typeof error === 'object' && error.message) || error);
}

function finishAnswer({ answer, saveError }) {
  if (!saveError) return answer;
  const text = `${MESSAGES.store_warning}\n\n${answer.text}`;
  return { ...answer, text, answer: text, store_error: `assistant_turn: ${saveError}` };
}

return [{ json: finishAnswer({ answer: $('Antwoord opbouwen').first().json, saveError: nodeError($json) }) }];
